<?php require __DIR__.'/../bootstrap.php';require_login();$tid=(int)getv('thread');$file=basename((string)getv('file'));$s=db()->prepare('SELECT 1 FROM support_threads WHERE id=? AND user_id=?');$s->execute([$tid,current_user()['id']]);$ok=(bool)$s->fetchColumn();if(!$ok&&current_user()['role']!=='admin')exit('Forbidden');$path=__DIR__.'/../uploads/payments/'.$file;if(!is_file($path))exit('Not found');$mime=mime_content_type($path)?:'application/octet-stream';header('Content-Type: '.$mime);header('Content-Length: '.filesize($path));readfile($path);exit;